cat > /etc/nginx/sites-available/cache << 'EOF'
server {
  listen 80;
  location /static/ {
    expires 30d;
    add_header Cache-Control "public, immutable";
  }
  location / {
    proxy_pass http://backend;
    proxy_cache mycache;
    proxy_cache_valid 200 1h;
  }
}
EOF

echo -e 'upstream backend {
  server 192.168.1.10:80 weight=3;
  server 192.168.1.11:80;
  server 192.168.1.12:80 backup;
}' > /etc/nginx/sites-available/upstream && nginx -s reload

echo -e 'upstream backend {
  ip_hash;
  server 192.168.1.10:80;
  server 192.168.1.11:80;
}' >> /etc/nginx/sites-available/upstream && nginx -s reload

cat > /etc/nginx/sites-available/http3 << 'EOF'
server {
  listen 443 quic reuseport;
  listen 443 ssl http2;
  add_header Alt-Svc 'h3=":443"; ma=86400';
}
EOF && nginx -s reload

cat > /etc/nginx/sites-available/websocket << 'EOF'
server {
  listen 80;
  location /ws {
    proxy_pass http://websocket-backend:8080;
    proxy_http_version 1.1;
    proxy_set_header Upgrade $http_upgrade;
    proxy_set_header Connection "upgrade";
  }
}
EOF

apt install -y apache2-utils && htpasswd -c /etc/nginx/.htpasswd john && echo -e '
location /admin {
  auth_basic "Restricted";
  auth_basic_user_file /etc/nginx/.htpasswd;
}' >> /etc/nginx/sites-available/default && nginx -s reload

echo -e 'geo $blocked_country {
  default 0;
  CN 1;
  RU 1;
}
server {
  if ($blocked_country) { return 403; }
}' > /etc/nginx/sites-available/geoblock && nginx -s reload

echo -e 'limit_req_zone $binary_remote_addr zone=api:10m rate=5r/s;
server {
  location /api/ {
    limit_req zone=api burst=10 nodelay;
    proxy_pass http://api_backend;
  }
}' > /etc/nginx/sites-available/ratelimit && nginx -s reload

echo -e 'site1.example.com {
  root * /var/www/site1
  file_server
}

site2.example.com {
  reverse_proxy localhost:8000
}' > /etc/caddy/Caddyfile && caddy reload
